      "reference_scene_index": 4,
      "lines": [
        {
          "speaker": "Eric",
          "text": "You sold it for more than you paid, but is that the whole story?",
          "vi": "Bạn bán với giá cao hơn giá mua, nhưng đó đã là toàn bộ câu chuyện chưa?"
        },
        {
          "speaker": "Jade",
          "text": "Not quite. I still need to factor in the vet bills.",
          "vi": "Chưa hẳn. Tôi vẫn phải tính thêm hóa đơn thú y."
        },
        {
          "speaker": "Eric",
          "text": "Then the difference in price is not your net profit.",
          "vi": "Vậy chênh lệch giá chưa phải lợi nhuận ròng."
        },
        {
          "speaker": "Jade",
          "text": "Exactly. I should calculate the full cost first.",
          "vi": "Chính xác. Tôi nên tính đầy đủ chi phí trước."
        }
      ],
