      "lines": [
        {
          "speaker": "Jordan",
          "text": "I apologise for being late. The visitor entrance was changed.",
          "vi": "Tôi xin lỗi vì đến muộn. Lối vào dành cho khách đã đổi."
        },
        {
          "speaker": "Assistant",
          "text": "I see. The interviewer is still available for a short meeting.",
          "vi": "Tôi hiểu. Người phỏng vấn vẫn có thể gặp ngắn."
        },
        {
          "speaker": "Jordan",
          "text": "Would it be possible to use that time to explain my experience?",
          "vi": "Liệu tôi có thể dùng thời gian đó để trình bày kinh nghiệm không?"
        },
        {
          "speaker": "Assistant",
          "text": "Yes. Please follow me to the interview room.",
          "vi": "Được. Xin mời đi theo tôi tới phòng phỏng vấn."
        }
      ],
