      "level": "B2",
      "order": 140,
      "title": "Hỏi thăm đồng nghiệp với sự quan tâm đúng mực",
      "topic": "Nhận biết sự cô lập nơi làm việc và hỏi han không đưa ra phán xét.",
      "description": "Bối cảnh phim/TV: Nhận biết sự cô lập nơi làm việc và hỏi han không đưa ra phán xét.. Hội thoại gốc do PeakFour biên soạn để luyện nghe và viết.",
      "track": "conversation",
