      "topic_group": "shopping",
      "scene_context_vi": "Rachel khoe giống mèo Sphynx thuần chủng với bạn bè; mọi người trêu về ngoại hình và hỏi giá mua.",
      "context_review": "scene_specific_editorial_checked"
