      "topic_group": "career",
      "scene_context_vi": "Mike quan sát sảnh khách sạn và hỏi nhân viên về bể bơi, giờ giấc trong khi Harvey chuẩn bị phỏng vấn.",
      "context_review": "scene_specific_editorial_checked"
