      "scene_context_vi": "Chandler thông báo được thăng chức ở công việc tạm thời đã làm năm năm, rồi bất ngờ tuyên bố nghỉ vì không muốn gắn bó nghề này.",
      "context_review": "scene_specific_editorial_checked"
