      "scene_context_vi": "Rachel bị ngã khi tháo đèn trang trí và có thể bị thương ở chân. Monica giải thích tình trạng với lễ tân bệnh viện; họ được yêu cầu điền thông tin cá nhân, liên hệ khẩn cấp và bảo hiểm.",
