      "scene_context_vi": "Rachel phát hiện mình không có bảo hiểm và lo ngại chi phí chụp X-quang. Cô gợi ý dùng bảo hiểm của Monica, nhưng Monica chỉ rõ đó là gian lận bảo hiểm.",
