      "topic": "Nghỉ làm tạm thời vì mất kiểm soát cảm xúc",
      "description": "Ross kể đã gặp bác sĩ tâm thần tại công ty sau khi quát sếp và được yêu cầu nghỉ phép. Anh nói mình đã dùng thuốc được kê và dường như bớt bận tâm về chiếc bánh.",
      "scene_context_vi": "Ross kể đã gặp bác sĩ tâm thần tại công ty sau khi quát sếp và được yêu cầu nghỉ phép. Anh nói mình đã dùng thuốc được kê và dường như bớt bận tâm về chiếc bánh.",
