          "speaker": "Ross",
          "text": "Evolution is not one of those things! Evolution is a scientific fact! Like the air we breathe, like gravity!",
          "vi": "Tiến hóa không phải chuyện kiểu vậy! Đó là sự thật khoa học! Giống như không khí ta hít thở, hay trọng lực!",
          "source_turn": 5,
